import os
import sqlite3
import hashlib
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/app/data/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        email TEXT,
        role TEXT DEFAULT 'user',
        password_hash TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS api_keys (
        id INTEGER PRIMARY KEY,
        user_id INTEGER,
        key_hash TEXT,
        scope TEXT DEFAULT 'read',
        FOREIGN KEY(user_id) REFERENCES users(id)
    )''')
    db.execute("INSERT OR IGNORE INTO users (id, username, email, role, password_hash) VALUES (1, 'admin', 'admin@corp.internal', 'admin', 'redacted')")
    db.execute("INSERT OR IGNORE INTO users (id, username, email, role, password_hash) VALUES (2, 'svc-reporting', 'svc@corp.internal', 'service', 'redacted')")
    db.execute("INSERT OR IGNORE INTO users (id, username, email, role, password_hash) VALUES (3, 'jdoe', 'jdoe@example.com', 'user', 'redacted')")
    db.commit()
    db.close()

@app.route('/api/users/search')
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('value', '')

    # Validate field name against allowed columns
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid field'}), 400

    # Build query with parameterized field (field is validated above)
    # but value is used in LIKE pattern
    query = f"SELECT id, username, email, role FROM users WHERE {field} LIKE '%' || ? || '%'"

    try:
        db = get_db()
        results = db.execute(query, (value,)).fetchall()
        return jsonify([dict(row) for row in results])
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/users/<int:user_id>/keys', methods=['GET'])
def get_user_keys(user_id):
    """Retrieve API keys for a user. Internal use only."""
    db = get_db()
    keys = db.execute('SELECT id, scope FROM api_keys WHERE user_id = ?', (user_id,)).fetchall()
    return jsonify([dict(k) for k in keys])

@app.route('/api/report')
def generate_report():
    """Generate a user report. Accepts custom SQL for advanced filtering."""
    base_query = request.args.get('q', '')
    report_type = request.args.get('type', 'summary')

    if not base_query:
        return jsonify({'error': 'Query parameter q is required'}), 400

    # Restrict to SELECT statements only
    normalized = base_query.strip().upper()
    if not normalized.startswith('SELECT'):
        return jsonify({'error': 'Only SELECT queries allowed'}), 403

    # Block dangerous keywords
    dangerous = ['DROP', 'DELETE', 'INSERT', 'UPDATE', 'ALTER', 'EXEC', 'UNION']
    for kw in dangerous:
        if kw in normalized:
            return jsonify({'error': f'Keyword {kw} not allowed'}), 403

    try:
        db = get_db()
        cursor = db.execute(base_query)
        columns = [desc[0] for desc in cursor.description] if cursor.description else []
        rows = cursor.fetchall()
        return jsonify({'columns': columns, 'data': [list(r) for r in rows]})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

if __name__ == '__main__':
    os.makedirs('/app/data', exist_ok=True)
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
